package openapi

import (
	_ "fmt"
	_ "path"
	_ "strings"

	"example.internal/apikit/v3/expr"
)

type (
	// Version identifies an OpenAPI specification version generated by Apikit.
	Version string

	// Spec describes one OpenAPI document to generate: the specification
	// version it conforms to and its output path. The path is
	// slash-separated, relative to the gen directory and does not include
	// an extension: each document is written both as <path>.json and
	// <path>.yaml.
	Spec struct {
		// Version is the OpenAPI specification version of the document.
		Version Version
		// Path is the output path of the document relative to the gen
		// directory, without extension.
		Path string
	}
)

const (
	// Version20 identifies the Swagger (OpenAPI) 2.0 specification.
	Version20 Version = "2.0"
	// Version30 identifies the OpenAPI 3.0.3 specification.
	Version30 Version = "3.0"
	// Version32 identifies the OpenAPI 3.2.0 specification.
	Version32 Version = "3.2"
)

const (
	// DefaultPath20 is the default output path of the Swagger 2.0
	// document relative to the gen directory, without extension.
	DefaultPath20 = "http/openapi"
	// DefaultPath30 is the default output path of the OpenAPI 3.0.3
	// document relative to the gen directory, without extension.
	DefaultPath30 = "http/openapi3"
	// DefaultPath32 is the default output path of the OpenAPI 3.2.0
	// document relative to the gen directory, without extension.
	DefaultPath32 = "http/openapi3.2"
)

// versionsMetaKey is the API meta key used to select the generated OpenAPI
// specification versions.
const versionsMetaKey = "openapi:versions"

// pathMetaPrefix is the prefix of the API meta keys used to override the
// output paths of the generated OpenAPI documents.
const pathMetaPrefix = "openapi:path:"

// specDefaults lists the supported OpenAPI versions with their default output
// paths in generation order. The order matters: the example generator used to
// compute schema examples is stateful and generating the documents in a
// stable order keeps the examples of each document stable.
var specDefaults = []Spec{
	{Version20, DefaultPath20},
	{Version30, DefaultPath30},
	{Version32, DefaultPath32},
}

// Specs computes the OpenAPI documents to generate from the given API meta.
// The "openapi:versions" meta selects the generated versions and defaults to
// all supported versions. The "openapi:path:<version>" meta overrides the
// output path of the corresponding document. Specs returns the documents in
// generation order (2.0, 3.0 then 3.2) and errors on invalid version or path
// values.
func Specs(meta expr.MetaExpr) ([]Spec, error) {
	panic("excised: Specs")
}

// selectedVersions computes the set of OpenAPI versions to generate from the
// "openapi:versions" meta. It errors on unknown version values.
func selectedVersions(meta expr.MetaExpr) (map[Version]bool, error) {
	panic("excised: selectedVersions")
}

// specPath computes the output path of the document with the given defaults,
// honoring the "openapi:path:<version>" meta. It errors when the override is
// not a clean extension-less path relative to the gen directory.
func specPath(meta expr.MetaExpr, d Spec) (string, error) {
	panic("excised: specPath")
}

// validatePathKeys errors when the given meta contains an
// "openapi:path:<version>" key with an unknown version suffix. This catches
// typos such as "openapi:path:3.0.3" which would otherwise be silently
// ignored.
func validatePathKeys(meta expr.MetaExpr) error {
	panic("excised: validatePathKeys")
}

// knownVersion reports whether val names a supported OpenAPI version.
func knownVersion(val string) bool {
	panic("excised: knownVersion")
}
